import{z as l,x as A,o as E,c as p,q as n,j as o,D as t,d as r,s as i,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Myerson–Satterthwaite 原文","description":"","frontmatter":{"title":"Myerson–Satterthwaite 原文","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ms-1983-paper.md","filePath":"econ/ms-1983-paper.md","lastUpdated":1791413859000}'),d={name:"econ/ms-1983-paper.md"};function h(m,a,D,C,c,f){const s=A("Mermaid");return E(),p("div",null,[a[2]||(a[2]=n('<h1 id="myerson–satterthwaite-原文" tabindex="-1">Myerson–Satterthwaite 原文 <a class="header-anchor" href="#myerson–satterthwaite-原文" aria-label="Permalink to &quot;Myerson–Satterthwaite 原文&quot;">​</a></h1><div class="epigraph"><p>买卖双方估值独立、私人、连续分布时，没有机制能同时做到激励相容、事中个人理性、预算平衡，并且一定有效率。</p><footer>—— Myerson and Satterthwaite, Efficient Mechanisms for Bilateral Trading, Journal of Economic Theory, 1983</footer></div><p>附录对照，不插入主干。<a href="/econ/mirrlees-1971-paper">上一课</a>对照的是技能不可观察时的最优税。本篇对照 <strong>Myerson–Satterthwaite 1983 原文的问题设定</strong>：一个卖家一件物、一个买家，没有外面的补贴者，还要求有效配置。主干<a href="/econ/myerson-satterthwaite">Myerson–Satterthwaite</a>已取不可能与沟；这里对照 <em>JET</em> 短文如何用虚拟价值把双边交易写成无补贴下的不可能，以及它相对 Myerson 1981 卖方最优差在哪一块约束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Vickrey 对多方拍卖可以有效且占优，但卖方是机制的设计者，预算不必在买卖之间平衡。双边交易里，买卖双方都有私人估值，都要自愿（事中 IR），机制不能从外面输血（事后或事中预算平衡），还想要事后有效——估值更高者得物。Myerson 与 Satterthwaite 的缺口是：在独立连续分布、风险中性、拟线性下，这四件事不相容，除非分布退化到几乎没有贸易收益的刀刃。</p><p>原文不是「讨价还价会失败」的经验句。它是机制集合上的不可能：任何 IC+IR+BB 的机制，期望贸易必须少于有效水平，中间留下一条沟。</p><p><span class="marginnote">Myerson and Satterthwaite, <em>Journal of Economic Theory</em> 29, 1983, 265–281。不要发明 arXiv。事中 IR 比事前 IR 更强：签订时已知道自己的类型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>显示原理，只搜真话直接机制。买家虚拟价值 \\(\\varphi_b\\)、卖家虚拟成本 \\(\\varphi_s\\)，期望社会剩余写成虚拟剩余的期望。有效要求 \\(v_b\\ge v_s\\) 时一定交易；激励相容加事中 IR 却要求按 \\(\\varphi\\) 交易，并且把租金留给两边。两边的信息租金加起来，一般超过贸易的社会剩余，于是没有余钱同时付清租金又保持预算平衡。</p><p><span class="marginnote">「虚拟价值」翻译成大白话：把买家的报价打个折再算——因为想占便宜的人会压低报价，机制只能按「折扣后的估值」安排交易；卖家那边则把要价加成。折扣与加成的幅度由分布形状决定，信息租金越贵，折扣越狠。</span></p>',10)),(E(),o(B,null,{default:t(()=>[i(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20EFF%5B%22%E4%BA%8B%E5%90%8E%E6%9C%89%E6%95%88%3A%20vb%20%E5%A4%A7%E4%BA%8E%20vs%20%E5%88%99%E4%BA%A4%E6%98%93%22%5D%20--%3E%20GAP%5B%22%E4%BF%A1%E6%81%AF%E7%A7%9F%E9%87%91%E4%B8%A4%E8%BE%B9%E9%83%BD%E8%A6%81%22%5D%0A%20%20IR%5B%22%E4%BA%8B%E4%B8%AD%E4%B8%AA%E4%BA%BA%E7%90%86%E6%80%A7%22%5D%20--%3E%20GAP%0A%20%20BB%5B%22%E6%97%A0%E5%A4%96%E9%83%A8%E8%A1%A5%E8%B4%B4%22%5D%20--%3E%20GAP%0A%20%20GAP%20--%3E%20IMP%5B%22%E4%B8%8D%E8%83%BD%E5%9B%9B%E8%80%85%E5%90%8C%E6%97%B6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"Myerson 1981 只有卖方抽租，买方 IR 绑在参与上，预算由卖方吸收。1983 年双方都是参与者，没有委托人吸收赤字。这是约束集合的更换，不是把虚值公式重推一遍。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是双边信息租金。让买家说实话，必须给他低于估值的期望支付空间；让卖家说实话，必须给他高于成本的期望收入空间。有效贸易在中间类型上最薄，恰恰最需要双方都接近无租金——做不到。于是最优（例如最大化期望剩余）的机制故意在中间停掉一些有效贸易，以省租金。沟的宽度随分布重叠变大。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"数字实例：买家估值与卖家成本都服从 \\([0,100]\\) 均匀分布时，有效要求所有 \\(v_b\\ge v_s\\) 的组合都成交。机制却会在中间停手——「买家值 60、卖家要 55」这类差距很薄的组合最容易被放弃，因为两边索要的信息租金超过了这笔贸易本身的社会剩余。")],-1)),(E(),o(B,null,{default:t(()=>[i(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20OV%5B%22%E4%B9%B0%E5%8D%96%E4%BC%B0%E5%80%BC%E5%88%86%E5%B8%83%E9%87%8D%E5%8F%A0%22%5D%20--%3E%20MID%5B%22%E4%B8%AD%E9%97%B4%E7%B1%BB%E5%9E%8B%EF%BC%9A%E8%B4%B8%E6%98%93%E6%94%B6%E7%9B%8A%E6%9C%80%E8%96%84%22%5D%0A%20%20MID%20--%3E%20RENT%5B%22%E6%AD%A4%E5%A4%84%E6%9C%80%E9%9C%80%E5%8F%8C%E6%96%B9%E9%9B%B6%E7%A7%9F%E9%87%91%EF%BC%8C%E5%81%9A%E4%B8%8D%E5%88%B0%22%5D%0A%20%20RENT%20--%3E%20DROP%5B%22%E6%9C%80%E4%BC%98%E6%9C%BA%E5%88%B6%E6%95%85%E6%84%8F%E5%81%9C%E6%AD%A2%E9%83%A8%E5%88%86%E4%BA%A4%E6%98%93%22%5D%0A%20%20DROP%20--%3E%20GAPW%5B%22%E6%9C%9F%E6%9C%9B%E8%B4%B8%E6%98%93%E9%87%8F%E4%BD%8E%E4%BA%8E%E6%9C%89%E6%95%88%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20EDGE%5B%22%E4%BC%B0%E5%80%BC%E5%B7%AE%E8%B7%9D%E6%9E%81%E5%A4%A7%E7%9A%84%E4%B8%A4%E7%AB%AF%22%5D%20--%3E%20THICK%5B%22%E8%B4%B8%E6%98%93%E6%94%B6%E7%9B%8A%E5%8E%9A%EF%BC%8C%E7%A7%9F%E9%87%91%E4%BB%98%E5%BE%97%E8%B5%B7%22%5D%0A%20%20THICK%20--%3E%20FOC%5B%22%E6%8D%9F%E5%A4%B1%E9%9B%86%E4%B8%AD%E5%9C%A8%E4%B8%AD%E9%97%B4%E5%9C%B0%E5%B8%A6%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p>与 Mirrlees 所得税的对照：都是不可观察类型加 IC。税有一个委托人（政府）和资源约束；双边交易没有第三方出钱。附录链把两篇排在一起，不是说最优税是双边贸易的特例。</p><h3 id="对照主干-ms-课-不插入税与拍卖之间" tabindex="-1">对照主干 MS 课，不插入税与拍卖之间 <a class="header-anchor" href="#对照主干-ms-课-不插入税与拍卖之间" aria-label="Permalink to &quot;对照主干 MS 课，不插入税与拍卖之间&quot;">​</a></h3><p>主干<a href="/econ/myerson-satterthwaite">Myerson–Satterthwaite</a>已取不可能与「有效须补贴或放弃 IR」。本附录对照 <em>JET</em> 1983：虚拟剩余、连续独立分布、以及原文的交易机制设计语气。把 1983 插进 Mirrlees 原文之后只因为附录链如此排，<strong>不插入</strong>微观主干，也不把限价簿双边拍卖写成这篇的实施。</p><p><span class="marginnote">相关价值、共同价值、或多买家竞争会改结论。不可能钉在独立私人、连续、双边这一组家具上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>AGV 期望外部性用事前 IR 加预算的期望平衡，可以有效，但事中可能要某人付钱才能参与。那是后课，不是 1983 年的解。也不要把不可能写成「市场不该存在」：分散市场上有进入、有竞争、有补贴式的平台，家具换了。</p><p><span class="marginnote">常见误区：把不可能定理读成「议价注定失败」。它只说：在双边、私人独立估值、无补贴者的精确设定下，有效率必然打折；一旦换成多买家竞争、平台补贴或允许外部支付，结论就可能翻转。</span></p><p>读完回主干 MS 课。附录微观与均衡的论文对照链到此结束。</p><p>分布若几乎不重叠，贸易收益极大，租金相对可付，不可能的定量刺变弱——原文已经把刀刃写进去。</p><p>双向拍卖、平台补贴、多边竞争，都是换家具：要么放弃事中 IR，要么放弃严格 BB，要么不再是一对一。限价簿连续双向拍卖是协议，不是 1983 年机制集合里的一个元素。</p><p>读完回主干<a href="/econ/myerson-satterthwaite">Myerson–Satterthwaite</a>。微观附录链在此停，不再加税或匹配。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Myerson–Satterthwaite 1983：双边交易下 IC、事中 IR、预算平衡与事后有效不能兼得。</li><li>虚拟剩余把沟写成租金付不起有效贸易。</li><li>1981 年卖方最优有委托人吸收预算；1983 年没有。</li><li>限价簿双边拍卖是协议，不是这篇机制集合里的一个元素。</li><li>读完回主干 MS 课；微观附录链在此停。</li><li>AGV 用事前 IR 换有效，不是 1983 年的解。</li><li>出处：Myerson and Satterthwaite, <em>JET</em> 1983。</li></ul>',13))])}const M=l(d,[["render",h]]);export{_ as __pageData,M as default};
